}

public static int nullSafeHashCode(long[] array) {
    if (array == null) {
        return 0;
    }
    int result = 1;
    for (long element : array) {
        result = 31 * result + (int) (element ^ (element >>> 32));
    }
    return result;
}

private TreeNode<T> rotateRight(TreeNode<T> node) {
    TreeNode<T> parent = node.getParent();
    TreeNode<T> grandParent = parent.getParent();
    TreeNode<T> sibling = node.getSibling();

    // Rotate the node
    node.setParent(sibling);
    sibling.setParent(parent);
    parent.setParent(node);

    // Update the sibling's children
    if (sibling.getLeftChild() == node) {
        sibling.setLeftChild(node.getRightChild());
    } else {
        sibling.setRightChild(node.getRightChild());
    }

    // Update the node's children
    node.setLeftChild(sibling);
    node.setRightChild(parent);

    // Update the grand parent's child
    if (grandParent != null) {
        if (grandParent.getLeftChild() == parent) {
            grandParent.setLeftChild(node);
        } else {
            grandParent.setRightChild(node);
        }
    }

    return parent;
}

public static void addToClassPath(Vector<URL> cpV, String dir) {
    // Check if the directory exists
    File dirFile = new File(dir);
    if (!dirFile.exists()) {
        throw new IllegalArgumentException("Directory does not exist: " + dir);
    }

    // Get all the jar files in the directory
    File[] jarFiles = dirFile.listFiles(new FilenameFilter() {
        @Override
        public boolean accept(File dir, String name) {
            return name.endsWith(".jar");
        }
    });

    // Add the jar files to the classpath
    for (File jarFile : jarFiles) {
        try {
            cpV.add(jarFile.toURI().toURL());
        } catch (MalformedURLException e) {
            throw new IllegalArgumentException("Invalid jar file: " + jarFile.getName(), e);
        }
    }
}

