public int available() throws IOException {
    // Implement the available() method as per the InputStream#available() method
    // This method returns the number of bytes that can be read from the input stream without blocking.
    // If the input stream is empty, this method returns 0.
    // If the input stream is closed, this method returns -1.
    // If the input stream is not empty and not closed, this method returns the number of bytes that can be read from the input stream without blocking.

    // Check if the input stream is closed
    if (isClosed()) {
        return -1;
    }

    // Check if the input stream is empty
    if (isEmpty()) {
        return 0;
    }

    // Return the number of bytes that can be read from the input stream without blocking
    return (int) Math.min(getSize() - getPosition(), Integer.MAX_VALUE);
}

