public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> pathSegments = new ArrayList<>();

    if (u == null) {
        throw new IllegalArgumentException("URI cannot be null");
    }

    String path = u.getPath();
    if (path == null) {
        return pathSegments;
    }

    if (path.startsWith("/")) {
        path = path.substring(1);
    }

    String[] pathSegmentStrings = path.split("/");
    for (String pathSegmentString : pathSegmentStrings) {
        if (decode) {
            pathSegmentString = URLDecoder.decode(pathSegmentString, StandardCharsets.UTF_8);
        }
        pathSegments.add(new PathSegmentImpl(pathSegmentString));
    }

    return pathSegments;
}

