private void pop(final String descriptor) {
    // Check if the descriptor is a type descriptor
    if (descriptor.startsWith("L") || descriptor.startsWith("[")) {
        // Pop the type from the output frame stack
        outputFrameStack.pop();
    } else {
        // Check if the descriptor is a method descriptor
        if (descriptor.startsWith("(")) {
            // Pop the argument types from the output frame stack
            String[] argumentTypes = descriptor.substring(1).split(";");
            for (String argumentType : argumentTypes) {
                outputFrameStack.pop();
            }
        } else {
            // Throw an IllegalArgumentException if the descriptor is not a type or method descriptor
            throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
        }
    }
}

