final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    // Check if the constant pool entry index is valid
    if (constantPoolEntryIndex < 0 || constantPoolEntryIndex >= classFileBuffer.length) {
        throw new IllegalArgumentException("Invalid constant pool entry index: " + constantPoolEntryIndex);
    }

    // Check if the char buffer is large enough
    if (charBuffer.length < 2) {
        throw new IllegalArgumentException("Char buffer must be at least 2 characters long");
    }

    // Read the string from the constant pool entry
    final int stringLength = classFileBuffer[constantPoolEntryIndex];
    final int stringOffset = classFileBuffer[constantPoolEntryIndex + 1];
    final int stringEnd = stringOffset + stringLength;

    // Check if the string is valid
    if (stringEnd > classFileBuffer.length) {
        throw new IllegalArgumentException("String is not valid");
    }

    // Copy the string into the char buffer
    for (int i = 0; i < stringLength; i++) {
        charBuffer[i] = (char) classFileBuffer[stringOffset + i];
    }

    // Return the string
    return new String(charBuffer, 0, stringLength);
}

