    for (int i = 0; i < input.length(); i++) {
        char c = input.charAt(i);
        if (c == '\\') {
            i++;
            c = input.charAt(i);
            switch (c) {
                case 'n':
                    output.append('\n');
                    break;
                case 't':
                    output.append('\t');
                    break;
                case 'r':
                    output.append('\r');
                    break;
                case '\\':
                    output.append('\\');
                    break;
                default:
                    output.append(c);
                    break;
            }
        } else {
            output.append(c);
        }
    }
    return output.toString();
}

