private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // Check if the graph is null or the set of vertices is empty
    if (graph == null || vertices.isEmpty()) {
        throw new IllegalArgumentException("Graph or vertices cannot be null or empty");
    }

    // Check if all vertices are in the graph
    for (V vertex : vertices) {
        if (!graph.containsVertex(vertex)) {
            throw new IllegalArgumentException("Vertex " + vertex + " is not in the graph");
        }
    }

    // Check if the subgraph induced by the given vertices is complete
    for (V vertex1 : vertices) {
        for (V vertex2 : vertices) {
            if (vertex1 != vertex2 && !graph.containsEdge(vertex1, vertex2)) {
                return false;
            }
        }
    }

    return true;
}

